package extract_test

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"

	"github.com/tahardi/halo/backend/internal/extract"
	"github.com/tahardi/halo/backend/internal/model"
)

var (
	recordedAt = time.Date(2026, 10, 13, 16, 30, 0, 0, time.UTC)
	attackStart = time.Date(2026, 10, 13, 7, 0, 0, 0, time.UTC)
)

func meds() []model.Medication {
	return []model.Medication{
		{ID: "med-riza", Name: "Rizatriptan", UsualAmount: 1, Unit: "tablet", Kind: model.MedicationAcute},
		{ID: "med-ibu", Name: "Ibuprofen", UsualAmount: 400, Unit: "mg", Kind: model.MedicationAcute},
		{ID: "med-old", Name: "Sumatriptan", UsualAmount: 1, Unit: "tablet", Kind: model.MedicationAcute, Archived: true},
	}
}

func attack() model.Attack {
	return model.Attack{ID: "a1", StartedAt: attackStart, Timezone: "America/New_York"}
}

func empty() model.Proposal {
	return model.Proposal{
		Symptoms:           []model.Symptom{},
		Doses:              []model.ProposedDose{},
		UnknownMedications: []model.UnknownMedication{},
		Warnings:           []string{},
	}
}

func ts(s string) *string { return &s }

func num(f float64) *float64 { return &f }

func sev(n int) *int { return &n }

func at(t time.Time) *time.Time { return &t }

func TestValidate(t *testing.T) {
	tests := []struct {
		name string
		raw  extract.Raw
		want func(p *model.Proposal)
	}{
		{
			name: "happy path - nothing stated",
			raw:  extract.Raw{},
			want: func(_ *model.Proposal) {},
		},
		{
			name: "happy path - times converted to utc",
			raw: extract.Raw{
				StartedAt: ts("2026-10-13T03:00:00-04:00"),
				EndedAt:   ts("2026-10-13T11:00:00-04:00"),
			},
			want: func(p *model.Proposal) {
				p.StartedAt = at(time.Date(2026, 10, 13, 7, 0, 0, 0, time.UTC))
				p.EndedAt = at(time.Date(2026, 10, 13, 15, 0, 0, 0, time.UTC))
			},
		},
		{
			name: "error - time after recording dropped",
			raw:  extract.Raw{EndedAt: ts("2026-10-13T23:00:00-04:00")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped ended_at: after the recording time"}
			},
		},
		{
			name: "error - time more than 7 days before recording dropped",
			raw:  extract.Raw{StartedAt: ts("2026-10-01T03:00:00-04:00")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped started_at: more than 7 days before the recording"}
			},
		},
		{
			name: "error - time not rfc 3339 dropped",
			raw:  extract.Raw{StartedAt: ts("3 AM")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped started_at: not a valid time"}
			},
		},
		{
			name: "error - end before attack start dropped",
			raw:  extract.Raw{EndedAt: ts("2026-10-13T02:00:00-04:00")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped ended_at: before the start"}
			},
		},
		{
			name: "error - severity out of range dropped",
			raw:  extract.Raw{PeakSeverity: sev(11)},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped peak_severity: 11 is outside 0 to 10"}
			},
		},
		{
			name: "happy path - severity kept",
			raw:  extract.Raw{PeakSeverity: sev(8)},
			want: func(p *model.Proposal) { p.PeakSeverity = sev(8) },
		},
		{
			name: "happy path - symptoms cleaned and deduplicated",
			raw:  extract.Raw{Symptoms: []string{" Vomiting", "nausea", "vomiting", "hiccups"}},
			want: func(p *model.Proposal) {
				p.Symptoms = []model.Symptom{model.SymptomVomiting, model.SymptomNausea}
				p.Warnings = []string{`dropped unknown symptom "hiccups"`}
			},
		},
		{
			name: "happy path - dose matched case-insensitively",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: " rizatriptan ", Amount: num(1), TakenAt: ts("2026-10-13T03:00:00-04:00")},
			}},
			want: func(p *model.Proposal) {
				p.Doses = []model.ProposedDose{{MedicationID: "med-riza", Amount: 1, TakenAt: attackStart}}
			},
		},
		{
			name: "happy path - nickname is unknown never fuzzy matched",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: "riza", Amount: nil, TakenAt: ts("2026-10-13T06:00:00-04:00")},
				{Medication: "my triptan", Amount: num(1), TakenAt: nil},
			}},
			want: func(p *model.Proposal) {
				p.UnknownMedications = []model.UnknownMedication{
					{Name: "riza", TakenAt: at(time.Date(2026, 10, 13, 10, 0, 0, 0, time.UTC))},
					{Name: "my triptan", Amount: num(1)},
				}
			},
		},
		{
			name: "happy path - archived medicine is unknown",
			raw:  extract.Raw{Doses: []extract.RawDose{{Medication: "Sumatriptan"}}},
			want: func(p *model.Proposal) {
				p.UnknownMedications = []model.UnknownMedication{{Name: "Sumatriptan"}}
			},
		},
		{
			name: "happy path - missing amount uses usual amount",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: "Ibuprofen", TakenAt: ts("2026-10-13T06:00:00-04:00")},
			}},
			want: func(p *model.Proposal) {
				p.Doses = []model.ProposedDose{{
					MedicationID: "med-ibu",
					Amount:       400,
					TakenAt:      time.Date(2026, 10, 13, 10, 0, 0, 0, time.UTC),
				}}
			},
		},
		{
			name: "error - non-positive amount uses usual amount",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: "Ibuprofen", Amount: num(0), TakenAt: ts("2026-10-13T06:00:00-04:00")},
			}},
			want: func(p *model.Proposal) {
				p.Doses = []model.ProposedDose{{
					MedicationID: "med-ibu",
					Amount:       400,
					TakenAt:      time.Date(2026, 10, 13, 10, 0, 0, 0, time.UTC),
				}}
				p.Warnings = []string{"used usual amount for Ibuprofen: 0 is not a positive amount"}
			},
		},
		{
			name: "happy path - dose without time uses proposed start",
			raw: extract.Raw{
				StartedAt: ts("2026-10-13T02:00:00-04:00"),
				Doses:     []extract.RawDose{{Medication: "Rizatriptan"}},
			},
			want: func(p *model.Proposal) {
				start := time.Date(2026, 10, 13, 6, 0, 0, 0, time.UTC)
				p.StartedAt = at(start)
				p.Doses = []model.ProposedDose{{MedicationID: "med-riza", Amount: 1, TakenAt: start}}
				p.Warnings = []string{"used attack start as the time for Rizatriptan"}
			},
		},
		{
			name: "error - dose time in future uses attack start",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: "Rizatriptan", TakenAt: ts("2026-10-14T03:00:00-04:00")},
			}},
			want: func(p *model.Proposal) {
				p.Doses = []model.ProposedDose{{MedicationID: "med-riza", Amount: 1, TakenAt: attackStart}}
				p.Warnings = []string{
					"dropped taken_at for Rizatriptan: after the recording time",
					"used attack start as the time for Rizatriptan",
				}
			},
		},
		{
			name: "happy path - notes trimmed and blank notes null",
			raw:  extract.Raw{Notes: ts("   ")},
			want: func(_ *model.Proposal) {},
		},
		{
			name: "happy path - notes kept",
			raw:  extract.Raw{Notes: ts("  Big ride the night before. ")},
			want: func(p *model.Proposal) { p.Notes = ts("Big ride the night before.") },
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// given
			want := empty()
			tt.want(&want)

			// when
			got := extract.Validate(tt.raw, attack(), meds(), recordedAt)

			// then
			assert.Equal(t, want, got)
		})
	}
}

package extract

import (
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/tahardi/halo/backend/internal/model"
)

const (
	maxLookback = 7 * 24 * time.Hour
	maxSeverity = 10
)

type RawDose struct {
	Medication string   `json:"medication"`
	Amount     *float64 `json:"amount"`
	TakenAt    *string  `json:"taken_at"`
}

type Raw struct {
	StartedAt    *string   `json:"started_at"`
	EndedAt      *string   `json:"ended_at"`
	PeakSeverity *int      `json:"peak_severity"`
	Symptoms     []string  `json:"symptoms"`
	Doses        []RawDose `json:"doses"`
	Notes        *string   `json:"notes"`
}

type validator struct {
	recordedAt time.Time
	warnings   []string
}

func Validate(raw Raw, attack model.Attack, meds []model.Medication, recordedAt time.Time) model.Proposal {
	v := &validator{recordedAt: recordedAt, warnings: []string{}}
	p := model.Proposal{
		Symptoms:           []model.Symptom{},
		Doses:              []model.ProposedDose{},
		UnknownMedications: []model.UnknownMedication{},
	}

	p.StartedAt = v.time("started_at", raw.StartedAt)
	start := attack.StartedAt.UTC()
	if p.StartedAt != nil {
		start = *p.StartedAt
	}
	p.EndedAt = v.time("ended_at", raw.EndedAt)
	if p.EndedAt != nil && p.EndedAt.Before(start) {
		v.warn("dropped ended_at: before the start")
		p.EndedAt = nil
	}

	if raw.PeakSeverity != nil {
		if *raw.PeakSeverity < 0 || *raw.PeakSeverity > maxSeverity {
			v.warn(fmt.Sprintf("dropped peak_severity: %d is outside 0 to 10", *raw.PeakSeverity))
		} else {
			p.PeakSeverity = raw.PeakSeverity
		}
	}

	for _, s := range raw.Symptoms {
		sym := model.Symptom(strings.ToLower(strings.TrimSpace(s)))
		if !sym.Valid() {
			v.warn(fmt.Sprintf("dropped unknown symptom %q", strings.TrimSpace(s)))
			continue
		}
		if !slices.Contains(p.Symptoms, sym) {
			p.Symptoms = append(p.Symptoms, sym)
		}
	}

	for _, d := range raw.Doses {
		name := strings.TrimSpace(d.Medication)
		med, ok := findMedication(meds, name)
		if !ok {
			p.UnknownMedications = append(p.UnknownMedications, model.UnknownMedication{
				Name:    name,
				Amount:  d.Amount,
				TakenAt: v.time("taken_at for "+name, d.TakenAt),
			})
			continue
		}
		amount := med.UsualAmount
		if d.Amount != nil {
			if *d.Amount > 0 {
				amount = *d.Amount
			} else {
				v.warn(fmt.Sprintf("used usual amount for %s: %g is not a positive amount", med.Name, *d.Amount))
			}
		}
		takenAt := v.time("taken_at for "+med.Name, d.TakenAt)
		if takenAt == nil {
			v.warn("used attack start as the time for " + med.Name)
			takenAt = &start
		}
		p.Doses = append(p.Doses, model.ProposedDose{MedicationID: med.ID, Amount: amount, TakenAt: *takenAt})
	}

	if raw.Notes != nil {
		if n := strings.TrimSpace(*raw.Notes); n != "" {
			p.Notes = &n
		}
	}

	p.Warnings = v.warnings
	return p
}

func (v *validator) warn(msg string) {
	v.warnings = append(v.warnings, msg)
}

func (v *validator) time(field string, raw *string) *time.Time {
	if raw == nil {
		return nil
	}
	t, err := time.Parse(time.RFC3339, strings.TrimSpace(*raw))
	switch {
	case err != nil:
		v.warn("dropped " + field + ": not a valid time")
		return nil
	case t.After(v.recordedAt):
		v.warn("dropped " + field + ": after the recording time")
		return nil
	case t.Before(v.recordedAt.Add(-maxLookback)):
		v.warn("dropped " + field + ": more than 7 days before the recording")
		return nil
	}
	t = t.UTC()
	return &t
}

func findMedication(meds []model.Medication, name string) (model.Medication, bool) {
	for _, m := range meds {
		if !m.Archived && strings.EqualFold(strings.TrimSpace(m.Name), name) {
			return m, true
		}
	}
	return model.Medication{}, false
}

package extract_test

import (
	"context"
	"encoding/json"
	"errors"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"

	"github.com/tahardi/halo/backend/internal/extract"
	"github.com/tahardi/halo/backend/internal/model"
	"github.com/tahardi/halo/backend/mocks"
)

var errBoom = errors.New("boom")

type prompt struct {
	system string
	user   string
	schema map[string]any
}

func newClient(t *testing.T, reply any, err error) (*mocks.Client, *prompt) {
	t.Helper()
	got := &prompt{}
	client := mocks.NewClient(t)
	client.EXPECT().
		Structured(mock.Anything, mock.Anything, mock.Anything, mock.Anything, mock.Anything).
		RunAndReturn(func(_ context.Context, system string, user string, schema map[string]any, out any) error {
			got.system, got.user, got.schema = system, user, schema
			if err != nil {
				return err
			}
			encoded, marshalErr := json.Marshal(reply)
			if marshalErr != nil {
				return marshalErr
			}
			return json.Unmarshal(encoded, out)
		})
	return client, got
}

func input() extract.Input {
	return extract.Input{
		Transcript:  "Woke up at three with it, took a rizatriptan, threw up until about eleven.",
		Attack:      attack(),
		Medications: meds(),
		RecordedAt:  recordedAt,
	}
}

func TestExtractor_Extract(t *testing.T) {
	t.Run("happy path - returns validated proposal", func(t *testing.T) {
		// given
		client, _ := newClient(t, extract.Raw{
			EndedAt:  ts("2026-10-13T11:00:00-04:00"),
			Symptoms: []string{"vomiting"},
			Doses:    []extract.RawDose{{Medication: "rizatriptan", TakenAt: ts("2026-10-13T03:00:00-04:00")}},
		}, nil)
		extractor := extract.New(client)

		// when
		got, err := extractor.Extract(context.Background(), input())

		// then
		require.NoError(t, err)
		want := empty()
		want.EndedAt = at(attackStart.Add(8 * time.Hour))
		want.Symptoms = []model.Symptom{model.SymptomVomiting}
		want.Doses = []model.ProposedDose{{MedicationID: "med-riza", Amount: 1, TakenAt: attackStart}}
		assert.Equal(t, want, got)
	})

	t.Run("happy path - prompt carries transcript attack medicines timezone and recording time", func(t *testing.T) {
		// given
		client, got := newClient(t, extract.Raw{}, nil)
		extractor := extract.New(client)

		// when
		_, err := extractor.Extract(context.Background(), input())

		// then
		require.NoError(t, err)
		assert.Contains(t, got.user, input().Transcript)
		assert.Contains(t, got.user, "Timezone: America/New_York")
		assert.Contains(t, got.user, "Recorded at: 2026-10-13T12:30:00-04:00 (Tuesday)")
		assert.Contains(t, got.user, `"started_at":"2026-10-13T03:00:00-04:00"`)
		assert.Contains(t, got.user, `"name":"Rizatriptan"`)
		assert.NotContains(t, got.user, "Sumatriptan")
		assert.Contains(t, got.system, "never in the future")
		assert.Equal(t, "object", got.schema["type"])
	})

	t.Run("happy path - unknown timezone falls back to utc", func(t *testing.T) {
		// given
		client, got := newClient(t, extract.Raw{}, nil)
		extractor := extract.New(client)
		in := input()
		in.Attack.Timezone = "Mars/Olympus"

		// when
		_, err := extractor.Extract(context.Background(), in)

		// then
		require.NoError(t, err)
		assert.Contains(t, got.user, "Timezone: UTC")
		assert.Contains(t, got.user, "Recorded at: 2026-10-13T16:30:00Z (Tuesday)")
	})

	t.Run("error - client fails", func(t *testing.T) {
		// given
		client, _ := newClient(t, nil, errBoom)
		extractor := extract.New(client)

		// when
		_, err := extractor.Extract(context.Background(), input())

		// then
		assert.ErrorIs(t, err, errBoom)
	})
}

func TestExtractor_ModelName(t *testing.T) {
	// given
	client := mocks.NewClient(t)
	client.EXPECT().Name().Return("claude-opus-5-5")
	extractor := extract.New(client)

	// when
	got := extractor.ModelName()

	// then
	assert.Equal(t, "claude-opus-5-5", got)
}

package extract

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/tahardi/halo/backend/internal/model"
)

const systemPrompt = `You turn a spoken summary of one migraine attack into proposed updates to that attack's record.
You receive the speaker's timezone, the time the summary was recorded, the attack as currently stored, the speaker's
list of medicines, and a transcript.

Rules:
- Propose only what the speaker clearly stated. Leave a field null, or a list empty, when it was not said.
- Times: write every time as RFC 3339 with the offset of the speaker's timezone. A spoken time without a date
  ("woke up at three") means the most recent such time at or before the recording time, never in the future.
  "Last night" and "this morning" are relative to the recording time.
- started_at is when the attack began; ended_at is when it ended. Do not repeat the stored values unless the speaker
  changed them.
- peak_severity is the worst pain on a 0 to 10 scale, only if the speaker gave a number or a clear equivalent.
- symptoms uses only the allowed values in the schema.
- doses lists each medicine taken, one entry per dose. medication is the name exactly as it appears in the medicine
  list when the speaker clearly means that medicine; otherwise the name as spoken. Never guess a medicine from a
  nickname or a drug class. amount is the number of units if stated, otherwise null. taken_at is null if no time was
  said.
- notes is one to three plain sentences in the first person with context the speaker gave about the attack or the
  hours before it (sleep, food, drink, exercise, stress, travel), or null if none.`

type promptAttack struct {
	StartedAt     string   `json:"started_at"`
	EndedAt       *string  `json:"ended_at"`
	PeakSeverity  *int     `json:"peak_severity"`
	Symptoms      []string `json:"symptoms"`
	SymptomsOther *string  `json:"symptoms_other"`
	Notes         *string  `json:"notes"`
}

type promptMedication struct {
	Name        string  `json:"name"`
	UsualAmount float64 `json:"usual_amount"`
	Unit        string  `json:"unit"`
}

func nullable(t string) map[string]any {
	return map[string]any{"type": []string{t, "null"}}
}

func object(properties map[string]any) map[string]any {
	required := make([]string, 0, len(properties))
	for k := range properties {
		required = append(required, k)
	}
	return map[string]any{
		"type":                 "object",
		"additionalProperties": false,
		"required":             required,
		"properties":           properties,
	}
}

func symptomEnum() []string {
	out := make([]string, 0, len(model.Symptoms))
	for _, s := range model.Symptoms {
		out = append(out, string(s))
	}
	return out
}

var schema = object(map[string]any{
	"started_at":    nullable("string"),
	"ended_at":      nullable("string"),
	"peak_severity": nullable("integer"),
	"symptoms": map[string]any{
		"type":  "array",
		"items": map[string]any{"type": "string", "enum": symptomEnum()},
	},
	"doses": map[string]any{
		"type": "array",
		"items": object(map[string]any{
			"medication": map[string]any{"type": "string"},
			"amount":     nullable("number"),
			"taken_at":   nullable("string"),
		}),
	},
	"notes": nullable("string"),
})

func location(name string) *time.Location {
	loc, err := time.LoadLocation(name)
	if err != nil || name == "" {
		return time.UTC
	}
	return loc
}

func userMessage(in Input) (string, error) {
	loc := location(in.Attack.Timezone)
	local := func(t time.Time) string { return t.In(loc).Format(time.RFC3339) }

	a := promptAttack{
		StartedAt:     local(in.Attack.StartedAt),
		PeakSeverity:  in.Attack.PeakSeverity,
		Symptoms:      []string{},
		SymptomsOther: in.Attack.SymptomsOther,
		Notes:         in.Attack.Notes,
	}
	if in.Attack.EndedAt != nil {
		e := local(*in.Attack.EndedAt)
		a.EndedAt = &e
	}
	for _, s := range in.Attack.Symptoms {
		a.Symptoms = append(a.Symptoms, string(s))
	}
	meds := []promptMedication{}
	for _, m := range in.Medications {
		if !m.Archived {
			meds = append(meds, promptMedication{Name: m.Name, UsualAmount: m.UsualAmount, Unit: m.Unit})
		}
	}

	attackJSON, err := json.Marshal(a)
	if err != nil {
		return "", fmt.Errorf("encoding attack: %w", err)
	}
	medsJSON, err := json.Marshal(meds)
	if err != nil {
		return "", fmt.Errorf("encoding medications: %w", err)
	}

	var b strings.Builder
	fmt.Fprintf(&b, "Timezone: %s\n", loc.String())
	fmt.Fprintf(&b, "Recorded at: %s (%s)\n\n", local(in.RecordedAt), in.RecordedAt.In(loc).Weekday())
	fmt.Fprintf(&b, "Attack:\n%s\n\n", attackJSON)
	fmt.Fprintf(&b, "Medicines:\n%s\n\n", medsJSON)
	fmt.Fprintf(&b, "Transcript:\n%s", in.Transcript)
	return b.String(), nil
}

package extract

import (
	"context"
	"fmt"
	"time"

	"github.com/tahardi/halo/backend/internal/llm"
	"github.com/tahardi/halo/backend/internal/model"
)

const PromptVersion = "1"

type Input struct {
	Transcript  string
	Attack      model.Attack
	Medications []model.Medication
	RecordedAt  time.Time
}

type Extractor struct {
	client llm.Client
}

func New(client llm.Client) *Extractor {
	return &Extractor{client: client}
}

func (e *Extractor) ModelName() string {
	return e.client.Name()
}

func (e *Extractor) Extract(ctx context.Context, in Input) (model.Proposal, error) {
	user, err := userMessage(in)
	if err != nil {
		return model.Proposal{}, err
	}
	var raw Raw
	if err := e.client.Structured(ctx, systemPrompt, user, schema, &raw); err != nil {
		return model.Proposal{}, fmt.Errorf("extracting summary: %w", err)
	}
	return Validate(raw, in.Attack, in.Medications, in.RecordedAt), nil
}
